36.  *      Shapefile Specification</a>
37.  */
38. public class ShapefileReader extends SimpleReader<SimpleFeature> {
39.   private static final Logger LOGGER = LoggerFactory.getLogger(ShapefileReader.class);
40. 
41.   private final FeatureCollection<SimpleFeatureType, org.opengis.feature.simple.SimpleFeature> inputSource;
42.   private final String[] attributeNames;
43.   private final ShapefileDataStore dataStore;
44.   private final String layer;
45.   private MathTransform transformToLatLon;
46. 
47.   public ShapefileReader(String sourceProjection, String sourceName, Path input) {
48.     super(sourceName);
49.     this.layer = input.getFileName().toString().replaceAll("\\.shp$", "");
50.     dataStore = open(input);
51.     try {
52.       String typeName = dataStore.getTypeNames()[0];
53.       FeatureSource<SimpleFeatureType, org.opengis.feature.simple.SimpleFeature> source = dataStore
54.         .getFeatureSource(typeName);
55. 
56.       inputSource = source.getFeatures(Filter.INCLUDE);
57.       CoordinateReferenceSystem src =
58.         sourceProjection == null ? source.getSchema().getCoordinateReferenceSystem() : CRS.decode(sourceProjection);
59.       CoordinateReferenceSystem dest = CRS.decode("EPSG:4326", true);
60.       transformToLatLon = findMathTransform(input, src, dest);
61.       if (transformToLatLon.isIdentity()) {
62.         transformToLatLon = null;
63.       }
64.       attributeNames = new String[inputSource.getSchema().getAttributeCount()];
65.       for (int i = 0; i < attributeNames.length; i++) {
66.         attributeNames[i] = inputSource.getSchema().getDescriptor(i).getLocalName();
67.       }
68.     } catch (IOException e) {
69.       throw new UncheckedIOException(e);
70.     } catch (FactoryException e) {
71.       throw new FileFormatException("Bad reference system", e);
72.     }
73.   }
74. 
75.   private static MathTransform findMathTransform(Path input, CoordinateReferenceSystem src,
76.     CoordinateReferenceSystem dest) throws FactoryException {
77.     try {
78.       return CRS.findMathTransform(src, dest);
79.     } catch (OperationNotFoundException e) {
80.       var result = CRS.findMathTransform(src, dest, true);
81.       LOGGER.warn(
82.         "Failed to parse projection from {} (\"{}\") using lenient mode instead which may result in data inconsistencies",
83.         input.getFileName(), e.getMessage());
84.       return result;
85.     }
86.   }
87. 
88.   /**
89.    * Renders map features for all elements from an ESRI Shapefile based on the mapping logic defined in {@code profile}.
90.    * Overrides the coordinate reference system defined in the shapefile.
91.    *
92.    * @param sourceProjection code for the coordinate reference system of the input data, to be parsed by
93.    *                         {@link CRS#decode(String)}
94.    * @param sourceName       string ID for this reader to use in logs and stats
95.    * @param sourcePaths      paths to the {@code .shp} files on disk, or {@code .zip} files containing the shapefile
96.    *                         components
97.    * @param writer           consumer for rendered features
98.    * @param config           user-defined parameters controlling number of threads and log interval
99.    * @param profile          logic that defines what map features to emit for each source feature
100.    * @param stats            to keep track of counters and timings
101.    * @throws IllegalArgumentException if a problem occurs reading the input file
102.    */
103.   public static void processWithProjection(String sourceProjection, String sourceName, List<Path> sourcePaths,
104.     FeatureGroup writer, PlanetilerConfig config, Profile profile, Stats stats) {
105.     SourceFeatureProcessor.processFiles(
106.       sourceName,
107.       sourcePaths,
108.       path -> new ShapefileReader(sourceProjection, sourceName, path),
109.       writer, config, profile, stats
110.     );
111.   }
112. 
113.   private ShapefileDataStore open(Path path) {
114.     try {
115.       var store = new ShapefileDataStore(path.toUri().toURL());
116.       store.setTryCPGFile(true);
117.       return store;
118.     } catch (IOException e) {
119.       throw new IllegalArgumentException(e);
120.     }
121.   }
122. 
123.   @Override
124.   public long getFeatureCount() {
125.     return inputSource.size();
126.   }
127. 
128.   @Override
129.   public void readFeatures(Consumer<SimpleFeature> next) throws TransformException {
130.     long id = 0;
131.     try (var iter = inputSource.features()) {
132.       while (iter.hasNext()) {
133.         org.opengis.feature.simple.SimpleFeature feature = iter.next();
134.         Geometry source = (Geometry) feature.getDefaultGeometry();
135.         Geometry latLonGeometry = source;
136.         if (transformToLatLon != null) {
137.           latLonGeometry = JTS.transform(source, transformToLatLon);
138.         }
139.         if (latLonGeometry != null) {
140.           SimpleFeature geom = SimpleFeature.create(latLonGeometry, new HashMap<>(attributeNames.length),
141.             sourceName, layer, ++id);
142.           for (int i = 1; i < attributeNames.length; i++) {
143.             geom.setTag(attributeNames[i], feature.getAttribute(i));
144.           }
145.           next.accept(geom);
146.         }
147.       }
148.     }
149.   }
150. 
151.   @Override
152.   public void close() {
153.     dataStore.dispose();
154.   }
155. }
