31. /**
32.  * Utility that reads {@link SourceFeature SourceFeatures} from the vector geometries contained in a GeoPackage file.
33.  */
34. public class GeoPackageReader extends SimpleReader<SimpleFeature> {
35.   private static final Logger LOGGER = LoggerFactory.getLogger(GeoPackageReader.class);
36. 
37.   private final boolean keepUnzipped;
38.   private Path extractedPath = null;
39.   private final GeoPackage geoPackage;
40.   private final MathTransform coordinateTransform;
41. 
42.   GeoPackageReader(String sourceProjection, String sourceName, Path input, Path tmpDir, boolean keepUnzipped) {
43.     super(sourceName);
44.     this.keepUnzipped = keepUnzipped;
45. 
46.     if (sourceProjection != null) {
47.       try {
48.         var sourceCRS = CRS.decode(sourceProjection);
49.         var latLonCRS = CRS.decode("EPSG:4326");
50.         coordinateTransform = CRS.findMathTransform(sourceCRS, latLonCRS);
51.       } catch (FactoryException e) {
52.         throw new FileFormatException("Bad reference system", e);
53.       }
54.     } else {
55.       coordinateTransform = null;
56.     }
57. 
58.     try {
59.       geoPackage = openGeopackage(input, tmpDir);
60.     } catch (IOException e) {
61.       throw new UncheckedIOException(e);
62.     }
63.   }
64. 
65.   /**
66.    * Create a {@link GeoPackageManager} for the given path. If {@code input} refers to a file within a ZIP archive,
67.    * first extract it.
68.    */
69.   private GeoPackage openGeopackage(Path input, Path unzippedDir) throws IOException {
70.     var inputUri = input.toUri();
71.     if ("jar".equals(inputUri.getScheme())) {
72.       extractedPath = keepUnzipped ? unzippedDir.resolve(URLEncoder.encode(input.toString(), StandardCharsets.UTF_8)) :
73.         Files.createTempFile(unzippedDir, "", ".gpkg");
74.       FileUtils.createParentDirectories(extractedPath);
75.       if (!keepUnzipped || FileUtils.isNewer(input, extractedPath)) {
76.         try (var inputStream = inputUri.toURL().openStream()) {
77.           FileUtils.safeCopy(inputStream, extractedPath);
78.         }
79.       }
80.       return GeoPackageManager.open(false, extractedPath.toFile());
81.     }
82. 
83.     return GeoPackageManager.open(false, input.toFile());
84.   }
85. 
86. 
87.   /**
88.    * Renders map features for all elements from an OGC GeoPackage based on the mapping logic defined in {@code
89.    * profile}.
90.    *
91.    * @param sourceProjection code for the coordinate reference system of the input data, to be parsed by
92.    *                         {@link CRS#decode(String)}
93.    * @param sourceName       string ID for this reader to use in logs and stats
94.    * @param sourcePaths      paths to the {@code .gpkg} files on disk
95.    * @param tmpDir           path to temporary directory for extracting data from zip files
96.    * @param writer           consumer for rendered features
97.    * @param config           user-defined parameters controlling number of threads and log interval
98.    * @param profile          logic that defines what map features to emit for each source feature
99.    * @param stats            to keep track of counters and timings
100.    * @param keepUnzipped     to keep unzipped files around after running (speeds up subsequent runs, but uses more disk)
101.    * @throws IllegalArgumentException if a problem occurs reading the input file
102.    */
103.   public static void process(String sourceProjection, String sourceName, List<Path> sourcePaths, Path tmpDir,
104.     FeatureGroup writer, PlanetilerConfig config, Profile profile, Stats stats, boolean keepUnzipped) {
105.     SourceFeatureProcessor.processFiles(
106.       sourceName,
107.       sourcePaths,
108.       path -> new GeoPackageReader(sourceProjection, sourceName, path, tmpDir, keepUnzipped),
109.       writer, config, profile, stats
110.     );
111.   }
112. 
113.   @Override
114.   public long getFeatureCount() {
115.     long numFeatures = 0;
116. 
117.     for (String name : geoPackage.getFeatureTables()) {
118.       FeatureDao features = geoPackage.getFeatureDao(name);
119.       numFeatures += features.count();
120.     }
121.     return numFeatures;
122.   }
123. 
124.   @Override
125.   public void readFeatures(Consumer<SimpleFeature> next) throws Exception {
126.     var latLonCRS = CRS.decode("EPSG:4326");
127.     long id = 0;
128.     boolean loggedMissingGeometry = false;
129. 
130.     for (var featureName : geoPackage.getFeatureTables()) {
131.       FeatureDao features = geoPackage.getFeatureDao(featureName);
132. 
133.       // GeoPackage spec allows this to be 0 (undefined geographic CRS) or
134.       // -1 (undefined cartesian CRS). Both cases will throw when trying to
135.       // call CRS.decode
136.       long srsId = features.getSrsId();
137. 
138.       MathTransform transform = (coordinateTransform != null) ? coordinateTransform :
139.         CRS.findMathTransform(CRS.decode("EPSG:" + srsId), latLonCRS);
140. 
141.       for (var feature : features.queryForAll()) {
142.         GeoPackageGeometryData geometryData = feature.getGeometry();
143.         byte[] wkb;
144.         if (geometryData == null || (wkb = geometryData.getWkb()).length == 0) {
145.           if (!loggedMissingGeometry) {
146.             loggedMissingGeometry = true;
147.             LOGGER.warn("Geopackage file contains empty geometry: {}", geoPackage.getPath());
148.           }
149.           continue;
150.         }
151. 
152.         Geometry featureGeom = (new WKBReader()).read(wkb);
153.         Geometry latLonGeom = (transform.isIdentity()) ? featureGeom : JTS.transform(featureGeom, transform);
154. 
155.         FeatureColumns columns = feature.getColumns();
156.         SimpleFeature geom = SimpleFeature.create(latLonGeom, new HashMap<>(columns.columnCount()),
157.           sourceName, featureName, ++id);
158. 
159.         for (int i = 0; i < columns.columnCount(); ++i) {
160.           if (i != columns.getGeometryIndex()) {
161.             geom.setTag(columns.getColumnName(i), feature.getValue(i));
162.           }
163.         }
164. 
165.         next.accept(geom);
166.       }
167.     }
168.   }
169. 
170.   @Override
171.   public void close() throws IOException {
172.     geoPackage.close();
173. 
174.     if (!keepUnzipped && extractedPath != null) {
175.       FileUtils.delete(extractedPath);
176.     }
177.   }
178. }
179.

